"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["10579"],{10069(e){e.exports=JSON.parse('{"id":"FIN-205","slug":"stress-testing","term":"Stress Testing","also_known_as":[],"difficulty":"Intermediate","definition":"Stress testing examines how a business, bank or investment portfolio would cope under extreme but plausible adverse conditions, such as a severe recession, a market crash or a sudden rise in interest rates.","explanation":["Normal forecasts focus on expected outcomes. Stress tests deliberately look at bad outcomes, to check whether an organisation could survive them.","A stress test applies a severe shock to a financial model and measures the results. For a company, that might be a 30% fall in sales combined with higher borrowing costs. For a bank, it might be a deep recession with rising unemployment, falling property prices and many borrowers failing to repay.","For example, a company might find that it remains profitable if sales fall by 15%, but would breach its loan conditions and run short of cash if sales fell by 25%. That knowledge can lead it to hold more cash, reduce debt or arrange backup financing.","Banking regulators in many countries require large banks to run stress tests regularly to show they hold enough capital to absorb heavy losses and keep lending during a crisis. Stress tests do not predict what will happen; they reveal weaknesses so that action can be taken in advance."],"note":"","total":1500,"prev":{"slug":"strategic-buyer","term":"Strategic Buyer"},"next":{"slug":"strike-price","term":"Strike Price"}}')}}]);